-- Extensões reconstruídas: snapshot servidor-side, normalização quantitativa e Banco Nacional de Teses.
CREATE TABLE IF NOT EXISTS jec_dashboard_snapshots (id INT AUTO_INCREMENT PRIMARY KEY,snapshot_key VARCHAR(191) NOT NULL UNIQUE,version_hash VARCHAR(64) NOT NULL,payload_json LONGTEXT NOT NULL,source_status ENUM('official_aggregate','validated_snapshot','legacy_recovered') NOT NULL,active INT NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_jec_dashboard_active(active,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS jurisprudence_quantitative (id INT AUTO_INCREMENT PRIMARY KEY,jurisprudence_id INT NOT NULL UNIQUE,normalized_outcome ENUM('favoravel','desfavoravel','parcial','acordo','extincao','indeterminado') NOT NULL DEFAULT 'indeterminado',moral_damage_cents INT NULL,disposition_slug VARCHAR(191) NULL,normalized_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_jurisprudence_quantitative_record FOREIGN KEY(jurisprudence_id) REFERENCES jurisprudence_records(id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_profiles (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL UNIQUE,public_id VARCHAR(64) NOT NULL UNIQUE,use_type ENUM('attack','defense','both') NOT NULL,favored_party VARCHAR(255) NULL,procedure VARCHAR(255) NULL,jurisdiction VARCHAR(255) NULL,instance VARCHAR(128) NULL,argumentation LONGTEXT NULL,assumptions LONGTEXT NULL,required_facts LONGTEXT NULL,exceptions LONGTEXT NULL,when_to_use LONGTEXT NULL,when_not_to_use LONGTEXT NULL,likely_defense LONGTEXT NULL,reply_strategy LONGTEXT NULL,risk_notes LONGTEXT NULL,lifecycle_status ENUM('draft','source_pending','source_confirmed','legal_review','counter_review','validated','contested','outdated','superseded','revoked','archived') NOT NULL DEFAULT 'draft',version INT NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_legal_thesis_profiles_status(lifecycle_status),CONSTRAINT fk_thesis_profile_thesis FOREIGN KEY(thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_versions (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,version INT NOT NULL,snapshot_json LONGTEXT NOT NULL,change_note TEXT NULL,created_by_user_id INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_legal_thesis_version(thesis_id,version),CONSTRAINT fk_thesis_version_thesis FOREIGN KEY(thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT,CONSTRAINT fk_thesis_version_user FOREIGN KEY(created_by_user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_legal_basis (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,authority_type ENUM('constitution','law','code','regulation','sumula','binding_sumula','repetitive_theme','irdr','iac','other') NOT NULL,norm VARCHAR(255) NOT NULL,provision VARCHAR(255) NULL,relevant_text LONGTEXT NULL,official_url VARCHAR(1024) NULL,source_status ENUM('official_confirmed','source_pending','secondary_pending','not_for_use') NOT NULL,last_verified_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_thesis_legal_basis_thesis(thesis_id),CONSTRAINT fk_thesis_basis_thesis FOREIGN KEY(thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_evidence_requirements (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,label VARCHAR(255) NOT NULL,description TEXT NULL,importance ENUM('required','recommended','contextual') NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_thesis_evidence_req_thesis(thesis_id),CONSTRAINT fk_thesis_evidence_thesis FOREIGN KEY(thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_counterarguments (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,related_thesis_id INT NULL,title VARCHAR(500) NOT NULL,argument LONGTEXT NOT NULL,recommended_response LONGTEXT NULL,source_status ENUM('official_confirmed','editorial_review','source_pending') NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_thesis_counterarguments_thesis(thesis_id),CONSTRAINT fk_thesis_counter_thesis FOREIGN KEY(thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT,CONSTRAINT fk_thesis_counter_related FOREIGN KEY(related_thesis_id) REFERENCES legal_theses(id) ON DELETE SET NULL ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_scores (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,thesis_version INT NOT NULL,legal_strength DECIMAL(5,2) NOT NULL,jurisprudential_consistency DECIMAL(5,2) NOT NULL,freshness DECIMAL(5,2) NOT NULL,evidence_quality DECIMAL(5,2) NOT NULL,composite_score DECIMAL(5,2) NOT NULL,methodology_version VARCHAR(64) NOT NULL,methodology_note TEXT NOT NULL,reviewed_by_user_id INT NULL,calculated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_legal_thesis_score_version(thesis_id,thesis_version),CONSTRAINT fk_thesis_score_version FOREIGN KEY(thesis_id,thesis_version) REFERENCES legal_thesis_versions(thesis_id,version) ON DELETE CASCADE ON UPDATE RESTRICT,CONSTRAINT fk_thesis_score_user FOREIGN KEY(reviewed_by_user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_metrics (id BIGINT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,thesis_version INT NOT NULL,tribunal VARCHAR(128) NULL,judging_body VARCHAR(255) NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,analyzed_count INT NOT NULL,favorable_count INT NOT NULL DEFAULT 0,unfavorable_count INT NOT NULL DEFAULT 0,partial_count INT NOT NULL DEFAULT 0,agreement_count INT NOT NULL DEFAULT 0,methodology_version VARCHAR(64) NOT NULL,sample_definition LONGTEXT NOT NULL,coverage_note LONGTEXT NOT NULL,source_status ENUM('official_aggregate','validated_sample','methodology_pending') NOT NULL,observed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_legal_thesis_metrics_version(thesis_id,thesis_version),CONSTRAINT fk_thesis_metric_version FOREIGN KEY(thesis_id,thesis_version) REFERENCES legal_thesis_versions(thesis_id,version) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_relations (id INT AUTO_INCREMENT PRIMARY KEY,source_thesis_id INT NOT NULL,target_thesis_id INT NOT NULL,relation ENUM('contradicts','refines','supersedes','related_to') NOT NULL,note TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_legal_thesis_relation(source_thesis_id,target_thesis_id,relation),CONSTRAINT fk_thesis_relation_source FOREIGN KEY(source_thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT,CONSTRAINT fk_thesis_relation_target FOREIGN KEY(target_thesis_id) REFERENCES legal_theses(id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legal_thesis_review_steps (id INT AUTO_INCREMENT PRIMARY KEY,thesis_id INT NOT NULL,thesis_version INT NOT NULL,stage ENUM('researcher','validator','counter_review','auditor') NOT NULL,status ENUM('pending','approved','rejected','returned') NOT NULL DEFAULT 'pending',reviewer_user_id INT NULL,note TEXT NULL,reviewed_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_legal_thesis_review_stage(thesis_id,thesis_version,stage),KEY idx_legal_thesis_review_version(thesis_id,thesis_version),CONSTRAINT fk_thesis_review_version FOREIGN KEY(thesis_id,thesis_version) REFERENCES legal_thesis_versions(thesis_id,version) ON DELETE CASCADE ON UPDATE RESTRICT,CONSTRAINT fk_thesis_review_user FOREIGN KEY(reviewer_user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
